function Test-PortScan {
    param([string]$Target, [int]$StartPort = 1, [int]$EndPort = 1024, [int]$Timeout = 100, [int]$Threads = 50)
    $openPorts = [System.Collections.Concurrent.ConcurrentBag[int]]::new()
    $range = $StartPort..$EndPort
    $chunks = $range | ForEach-Object -Parallel {
        $tcp = New-Object System.Net.Sockets.TcpClient
        $async = $tcp.BeginConnect($using:Target, $_, $null, $null)
        $wait = $async.AsyncWaitHandle.WaitOne($using:Timeout)
        if ($wait -and $tcp.Connected) {
            $openPorts.Add($_)
            $tcp.EndConnect($async)
        }
        $tcp.Close()
    } -ThrottleLimit $Threads
    $result = $openPorts.ToArray() | Sort-Object
    Write-SysLog "Port scan on $Target: $($result.Count) ports open"
    return $result
}

