function Invoke-DNSSpoofCheck {
    param([string]$Domain, [string]$TrustedDNSServer = '8.8.8.8')
    $trusted = (Resolve-DnsName $Domain -Server $TrustedDNSServer -ErrorAction SilentlyContinue).IPAddress | Select-Object -First 1
    $actual = (Resolve-DnsName $Domain -ErrorAction SilentlyContinue).IPAddress | Select-Object -First 1
    if (-not $trusted -or -not $actual) { return [PSCustomObject]@{ Domain=$Domain; TrustedIP=$trusted; ActualIP=$actual; Match=$false; Error='Resolution failed' } }
    $match = $trusted -eq $actual
    if (-not $match) { Write-SysLog "DNS SPOOF DETECTED: $Domain resolved to $actual but trusted says $trusted" -Level 'ERROR' }
    return [PSCustomObject]@{ Domain=$Domain; TrustedIP=$trusted; ActualIP=$actual; Match=$match; Error=$null }
}

