public static object GetHttpEndpointStatus(string url, int timeoutSeconds = 10, int expectedStatusCode = 200) {
    var sw = System.Diagnostics.Stopwatch.StartNew();
    try {
        var request = System.Net.WebRequest.CreateHttp(url);
        request.Timeout = timeoutSeconds * 1000;
        request.Method = "HEAD";
        using (var response = (System.Net.HttpWebResponse)request.GetResponse()) {
            sw.Stop();
            return new { IsUp = (int)response.StatusCode == expectedStatusCode, StatusCode = (int)response.StatusCode, ResponseTimeMs = sw.ElapsedMilliseconds, Error = (string)null };
        }
    } catch (Exception ex) {
        sw.Stop();
        return new { IsUp = false, StatusCode = 0, ResponseTimeMs = sw.ElapsedMilliseconds, Error = ex.Message };
    }
}

function convertUnits(value, from, to) {
    const conversions = {
        km_to_mi: v => v * 0.621371, mi_to_km: v => v * 1.60934,
        kg_to_lb: v => v * 2.20462, lb_to_kg: v => v * 0.453592,
        c_to_f: v => v * 9/5 + 32, f_to_c: v => (v - 32) * 5/9,
        gb_to_mb: v => v * 1024, mb_to_gb: v => v / 1024,
    };
    const key = `${from}_to_${to}`;
    return conversions[key] ? conversions[key](value) : value;
}

