function Repair-WindowsComponent {
    param([ValidateSet('DISM','SFC','Networking','PrintSpooler')][string]$Component, [string]$ComputerName = $env:COMPUTERNAME)
    $result = [PSCustomObject]@{ Component=$Component; Success=$false; Details='' }
    switch ($Component) {
        'DISM' {
            $output = Invoke-Command -ComputerName $ComputerName -ScriptBlock { dism /online /cleanup-image /restorehealth }
            $result.Success = $output -match 'operation completed successfully'
            $result.Details = $output
        }
        'SFC' {
            $output = Invoke-Command -ComputerName $ComputerName -ScriptBlock { sfc /scannow }
            $result.Success = $output -match 'did not find any integrity violations' -or $output -match 'repaired'
            $result.Details = $output
        }
        'Networking' {
            $cmds = @('ipconfig /release', 'ipconfig /renew', 'ipconfig /flushdns', 'netsh winsock reset')
            foreach ($cmd in $cmds) { Invoke-Command -ComputerName $ComputerName -ScriptBlock { param($c) cmd /c $c } -ArgumentList $cmd }
            $result.Success = $true
            $result.Details = 'Network stack reset'
        }
        'PrintSpooler' {
            Invoke-Command -ComputerName $ComputerName -ScriptBlock { Stop-Service Spooler; Start-Service Spooler }
            $result.Success = $true
            $result.Details = 'Print spooler restarted'
        }
    }
    Write-SysLog "Repair $Component on $ComputerName : $($result.Success)" -Level $(if($result.Success){'INFO'}else{'ERROR'})
    return $result
}

function Protect-String {
    param([string]$PlainText, [ValidateSet('DPAPI','AES')][string]$Method = 'DPAPI', [string]$Password = '')
    if ($Method -eq 'DPAPI') {
        $bytes = [System.Text.Encoding]::UTF8.GetBytes($PlainText)
        $encrypted = [System.Security.Cryptography.ProtectedData]::Protect($bytes, $null, [System.Security.Cryptography.DataProtectionScope]::CurrentUser)
        return [Convert]::ToBase64String($encrypted)
    } else {
        throw 'AES method requires implementation of key derivation'
    }
}

function Unprotect-String {
    param([string]$CipherText, [ValidateSet('DPAPI','AES')][string]$Method = 'DPAPI')
    if ($Method -eq 'DPAPI') {
        $bytes = [Convert]::FromBase64String($CipherText)
        $decrypted = [System.Security.Cryptography.ProtectedData]::Unprotect($bytes, $null, [System.Security.Cryptography.DataProtectionScope]::CurrentUser)
        return [System.Text.Encoding]::UTF8.GetString($decrypted)
    } else {
        throw 'AES method not implemented'
    }
}
